/* WEATHER ALERTS - a live p0pc0rn app (non-agentic: it checks on its own; Juli does not work in it). It watches the US National Weather Service's active alerts for ONE place the person types
   in, and posts each new warning into Juli's chat (once per alert). It also shows the forecast. Checks run only while p0pc0rn is open:
   every 90 minutes while an alert is active, every 12 hours when it is calm (and when p0pc0rn opens).
   Data: api.weather.gov through the host (p0.fetch). The place is kept on this phone only. */

// ===== SLOTS =====
const SL = window.SLOTS || {};
const TITLE = String(SL.title || 'Weather Alerts').slice(0, 22);
const ACCENT = /^#[0-9a-fA-F]{6}$/.test(SL.accent || '') ? SL.accent : '#ff9f0a';
const LEVELS = ['warnings', 'watches', 'all'];
const LEVEL0 = LEVELS.includes(SL.post_level) ? SL.post_level : 'watches';
const PLACE0 = String(SL.place_hint || '').slice(0, 60);

// ===== STATE (saved) =====
const KEY = 'wx.v1';
let st = { place: null, seen: [], level: LEVEL0, lastCheck: 0 };   // place = { name, lat, lon }
let data = { alerts: null, periods: null, err: null, at: 0, busy: false };
let ui = { query: PLACE0, results: null, searching: false, editing: false, contentH: 900 };
function loadSt() { st = Object.assign({ place: null, seen: [], level: LEVEL0, lastCheck: 0 }, K.load(KEY, {})); }
function saveSt() { K.save(KEY, st); }
loadSt();

// ===== THE CHECK (the host calls it on a timer and when p0pc0rn opens) =====
const sevOf = (a) => (a.severity === 'Extreme' || a.severity === 'Severe' || /warning|emergency/i.test(a.event) ? 'warning' : /watch/i.test(a.event) ? 'watch' : 'info');
function worthPosting(a) {
  const s = sevOf(a);
  if (s === 'warning') return true;
  if (s === 'watch') return st.level !== 'warnings';
  return st.level === 'all';
}
async function check() {
  loadSt();
  if (!st.place) return { active: false };
  const d = await p0.fetch('alerts.nws', { lat: st.place.lat, lon: st.place.lon });
  const list = d.alerts || [];
  let posted = 0;
  for (const a of list) {
    if (!a.id || st.seen.includes(a.id) || !worthPosting(a)) continue;
    try { await p0.chat.post({ title: a.event + ' · ' + st.place.name, severity: sevOf(a), text: a.headline || a.event }); }
    catch (e) { break; }   // the hour's notices are used up: the rest wait for the next check
    st.seen.push(a.id); st.seen = st.seen.slice(-200); saveSt(); posted++;   // remembered at once: never posted twice
  }
  st.lastCheck = Date.now(); saveSt();
  if (p0.mode === 'run') { data.alerts = list; data.at = Date.now(); }
  return { active: list.some((a) => sevOf(a) !== 'info'), posted };
}
if (window.p0) p0.onCheck(check);

// ===== DATA =====
async function refresh(quiet) {
  if (!st.place || data.busy || !window.p0) return;
  data.busy = true; data.err = null;
  try {
    const [al, fc] = await Promise.all([p0.fetch('alerts.nws', { lat: st.place.lat, lon: st.place.lon }), p0.fetch('weather.nws', { lat: st.place.lat, lon: st.place.lon }).catch(() => null)]);
    data.alerts = al.alerts || []; data.periods = fc ? fc.periods : null; data.at = Date.now();
    if (!quiet) K.toast('Updated', { tone: 'good', icon: 'refresh', ms: 1200 });
  } catch (e) { data.err = String((e && e.message) || e); if (!quiet) K.toast("Couldn't reach the weather service", { tone: 'bad', icon: 'cloud' }); }
  data.busy = false;
}
async function search() {
  const q = ui.query.trim();
  if (q.length < 2 || ui.searching) return;
  ui.searching = true; ui.results = null;
  try { ui.results = (await p0.fetch('geocode.openmeteo', { name: q })).results || []; if (!ui.results.length) K.toast('No place with that name', { tone: 'warn' }); }
  catch (e) { K.toast("Couldn't search for places", { tone: 'bad' }); }
  ui.searching = false;
}
function choose(r) {
  if (r.cc !== 'US') { K.toast('The National Weather Service covers the US only', { tone: 'warn', icon: 'alert', ms: 3000 }); return; }
  st.place = { name: [r.name, r.region].filter(Boolean).join(', ').slice(0, 60), lat: r.lat, lon: r.lon };
  st.seen = []; saveSt(); ui.results = null; ui.editing = false; K.blurInputs();
  K.sfx('success'); data.alerts = null; data.periods = null; refresh(true);
}

// ===== DRAWING =====
function setup() {
  K.setup({ mode: 'dark', accent: ACCENT });
  K.scene('main', drawMain);
  if (st.place && window.p0 && p0.mode === 'run') refresh(true);
}
function draw() { K.render(); }

function drawMain() {
  K.backdrop({ top: K.C.bg, bottom: K.darken(ACCENT, 0.82), glow: [{ x: K.W * 0.85, y: 80, r: 260, color: K.alpha(ACCENT, 0.18) }] });
  const sub = st.place ? 'Watching ' + st.place.name : 'Pick a place to watch';
  const top = K.navBar.top(sub) + 8, clipY = K.navBar.bottom(), w = K.W - 2 * K.S.l, x = K.S.l;
  const off = K.scroll('main', 0, clipY, K.W, K.H - clipY, ui.contentH);
  K.clip(0, clipY, K.W, K.H - clipY, () => { ui.contentH = body(x, top - off, w) + off - top + 40; });
  const tap = K.navBar(TITLE, off, { sub, right: st.place ? { id: 'refresh', icon: 'refresh' } : undefined });
  if (tap === 'refresh') refresh(false);
}

function body(x, y, w) {
  const y0 = y;
  if (!st.place || ui.editing) y = placePicker(x, y, w);
  else {
    K.card(x, y, w, 64, { r: 16 });
    K.icon('pin', x + 30, y + 32, 20, ACCENT);
    K.text(st.place.name, x + 54, y + 28, 'headline', K.C.text, { maxW: w - 150 });
    K.text(st.lastCheck ? 'Last check ' + K.fmt.ago(st.lastCheck) : 'Not checked yet', x + 54, y + 48, 'footnote', K.C.text3);
    if (K.button('change', x + w - 92, y + 14, 80, 36, 'Change', { style: 'tinted' })) { ui.editing = true; ui.query = ''; ui.results = null; }
    y += 80;
  }
  if (st.place && !ui.editing) {
    K.text('ACTIVE ALERTS', x, y + 14, 'label', K.C.text2); y += 26;
    if (data.busy && !data.alerts) { K.shimmer(x, y, w, 72, 16); y += 84; }
    else if (data.err && !data.alerts) { y += K.empty(K.W / 2, y + 10, 'cloud', 'Offline', 'The alerts will show when the weather service answers.', { w }) + 16; }
    else if (data.alerts && !data.alerts.length) { K.card(x, y, w, 64, { r: 16 }); K.icon('checkCircle', x + 30, y + 32, 20, K.C.good); K.text('No active alerts', x + 54, y + 37, 'body', K.C.text); y += 76; }
    else for (const [i, a] of (data.alerts || []).entries()) {
      const s = sevOf(a), col = s === 'warning' ? K.C.bad : s === 'watch' ? K.C.warn : ACCENT, hl = a.headline || a.area;
      const h = 64 + K.paraHeight(hl, w - 32, 'footnote', { maxLines: 4 });
      K.card(x, y, w, h, { r: 16 });
      K.rect(x, y + 12, 4, h - 24, { fill: col, r: 2 });
      K.text(a.event, x + 16, y + 28, 'headline', K.C.text, { maxW: w - 32 });
      K.text((a.ends ? 'Until ' + K.fmt.date(Date.parse(a.ends)) + ' ' + K.fmt.time12(Date.parse(a.ends)) : a.severity) + (a.sender ? ' · ' + a.sender : ''), x + 16, y + 48, 'caption', K.C.text3, { maxW: w - 32 });
      K.para(hl, x + 16, y + 60, w - 32, 'footnote', K.C.text2, { maxLines: 4 });
      y += h + 10; if (i > 12) break;
    }
    if (data.periods && data.periods.length) {
      K.text('FORECAST', x, y + 18, 'label', K.C.text2); y += 30;
      const rows = data.periods.slice(0, 6), rh = 52;
      K.card(x, y, w, rows.length * rh, { r: 16 });
      rows.forEach((p, i) => {
        const ry = y + i * rh;
        if (i) K.line(x + 16, ry, x + w - 16, ry, K.C.line, 1);
        K.icon(/rain|shower|storm/i.test(p.short) ? 'rain' : /cloud|fog/i.test(p.short) ? 'cloud' : p.day ? 'sun' : 'moon', x + 26, ry + rh / 2, 18, ACCENT);
        K.text(p.name, x + 48, ry + 22, 'subhead', K.C.text, { maxW: w * 0.45 });
        K.text(p.short, x + 48, ry + 40, 'caption', K.C.text3, { maxW: w - 140 });
        K.text(p.temp + '°' + p.unit, x + w - 16, ry + rh / 2 + 6, 'headline', K.C.text, { align: 'right' });
      });
      y += rows.length * rh + 12;
    }
    K.text('POST TO JULI’S CHAT', x, y + 18, 'label', K.C.text2); y += 30;
    const li = K.segmented('level', x, y, w, ['Warnings', '+ Watches', 'Everything'], LEVELS.indexOf(st.level));
    if (LEVELS[li] !== st.level) { st.level = LEVELS[li]; saveSt(); }
    y += 48;
    y += K.para('New alerts are posted to the chat once each. Checks run while p0pc0rn is open: every 90 minutes on active days, every 12 hours when calm.', x, y + 6, w, 'footnote', K.C.text3) + 10;
  }
  K.text('Data: US National Weather Service', x, y + 16, 'caption', K.C.text3);
  return y + 30 - y0;
}

function placePicker(x, y, w) {
  K.text('PLACE TO WATCH (US)', x, y + 14, 'label', K.C.text2); y += 24;
  ui.query = K.input('place', x, y, w - 96, 48, ui.query, { placeholder: 'Town or city', icon: 'pin', onEnter: search });
  if (K.button('find', x + w - 86, y, 86, 48, ui.searching ? '…' : 'Find', { style: 'primary', disabled: ui.searching })) search();
  y += 60;
  if (ui.results) for (const [i, r] of ui.results.entries()) {
    const row = K.listRow('res' + i, x, y, w, 56, { title: r.name, sub: [r.region, r.country].filter(Boolean).join(', '), icon: 'pin', iconColor: r.cc === 'US' ? ACCENT : K.C.text3, chevron: true, r: 14 });
    if (row.tap) choose(r);
    y += 62;
  }
  if (st.place && K.button('cancel', x, y + 4, w, 44, 'Keep ' + st.place.name, { style: 'ghost' })) { ui.editing = false; ui.results = null; K.blurInputs(); }
  return y + (st.place ? 60 : 12);
}
